head.b:skin:
/* Select input arrow icon */
.form-select {
    background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='white' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m2 5 6 6 6-6'/%3e%3c/svg%3e") !important;
    background-repeat: no-repeat !important;
    background-position: right 0.75rem center !important;
    background-size: 16px 12px !important;
    padding-right: 2.5rem !important;
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
}

/* Input field focus effect */
.form-control:focus, .form-select:focus, .budget-input:focus {
    border-color: #fe2c55 !important;
    box-shadow: 0 0 0 0.25rem rgba(254, 44, 85, 0.25) !important;
    outline: none !important;
}

/* Input field focus effect for specific form elements */
input:focus, select:focus, textarea:focus {
    border-color: #fe2c55 !important;
    box-shadow: 0 0 0 0.25rem rgba(254, 44, 85, 0.25) !important;
    outline: none !important;
}

/* Removed @import for speed optimization */

:root {
    --primary-color: #fe2c55;
    --secondary-color: #0a192f;
    --gold-primary: #ffd700;
    --gold-gradient: linear-gradient(135deg, #ffd700, #daa520);
    --dark-bg: #0b0e11;
    --tabs-bg: #0d213d;
}

body {
    font-family: 'Hind Siliguri', sans-serif !important;
    background: radial-gradient(circle at 0% 0%, #161a2e 0%, #0b0e11 100%) !important;
    color: white !important;
    padding-top: 75px;
}

header {
    background-color: #0a192f;
    padding: 0.6rem 20px;
    position: fixed;
    top: 0; width: 100%; z-index: 1000;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
    display: flex; justify-content: space-between; align-items: center;
}
@media (max-width: 480px) {
    header { padding: 0.6rem 12px; }
    .header-search { width: 130px !important; }
}
@media (max-width: 360px) {
    .header-search { width: 110px !important; }
    .logo img { height: 28px !important; }
}

.app-card {
    background: rgba(30, 41, 59, 0.7);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 20px;
    padding: 20px;
    backdrop-filter: blur(10px);
}
@media (max-width: 576px) {
    .app-card {
        padding: 15px;
    }
}

/* Capsule Tabs Style */
.tabs-btn-container {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 50px;
    padding: 5px;
    margin-bottom: 20px;
    max-width: 450px;
    margin-left: auto;
    margin-right: auto;
    display: flex;
}
.nav-pills {
    display: flex;
    gap: 0;
    width: 100%;
    padding: 0;
    margin: 0;
    list-style: none;
}
.nav-pills .nav-item {
    flex: 1;
}
.nav-pills .nav-link {
    width: 100%;
    background: transparent;
    color: rgba(255, 255, 255, 0.7);
    border-radius: 50px;
    padding: 12px 15px;
    font-weight: 600;
    border: none;
    transition: 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    position: relative;
    z-index: 1;
    cursor: pointer;
}
.nav-pills .nav-link.active {
    background: #fe2c55 !important;
    color: white !important;
    box-shadow: 0 8px 20px rgba(254, 44, 85, 0.3);
}

/* Budget Counter Styling */
.budget-counter {
    display: flex;
    align-items: stretch;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 15px;
    width: 100%;
    overflow: hidden;
}
.counter-btn {
    background: rgba(255, 255, 255, 0.1);
    border: none;
    color: white;
    padding: 10px;
    width: 60px;
    flex-shrink: 0;
    font-size: 1.5rem;
    cursor: pointer;
    transition: 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
}
@media (max-width: 576px) {
    .counter-btn {
        width: 50px;
        font-size: 1.2rem;
    }
}
.counter-btn:hover {
    background: rgba(254, 44, 85, 0.2);
    color: #fe2c55;
}
.budget-input {
    flex: 1;
    min-width: 0;
    background: transparent;
    border: none;
    color: white;
    text-align: center;
    font-size: 1.2rem;
    font-weight: 700;
    padding: 12px;
    outline: none;
}
.budget-input::-webkit-inner-spin-button, .budget-input::-webkit-outer-spin-button {
    -webkit-appearance: none; margin: 0;
}

/* Tight Fluid Single Line Estimate Styling */
.estimate-line {
    background: rgba(255, 255, 255, 0.03);
    border: 1px dashed rgba(255, 255, 255, 0.1);
    padding: 8px 10px;
    border-radius: 10px;
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
    align-items: center;
    margin-top: 15px;
}
.estimate-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    color: #fff;
    font-size: 0.8rem;
    flex-shrink: 0;
}
.estimate-badge i { color: #fe2c55; font-size: 0.85rem; }
.estimate-badge label { color: rgba(255, 255, 255, 0.6); margin-bottom: 0; }
.estimate-badge span.count-target { font-weight: 700; color: #3b82f6; }
.lowest-badge {
    color: #24E8E3 !important;
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    white-space: nowrap;
}

::placeholder {
    color: rgba(255, 255, 255, 0.6) !important;
    opacity: 1;
}

.text-tiktok-sm { color: #25f4ee; font-size: 0.8rem; }
.btn-tiktok {
    background: linear-gradient(135deg, #fe2c55 0%, #ee1d52 100%);
    border: none; color: white; font-weight: 600; border-radius: 12px; padding: 15px; transition: 0.3s;
}

.hero-slogan { 
    font-size: clamp(1.8rem, 5vw, 3.5rem); 
    font-weight: 800; 
    white-space: nowrap;
    width: 100%;
    overflow: hidden;
    color: #ffffff;
    margin-bottom: 10px;
}
@media (max-width: 950px) {
    .hero-slogan {
        white-space: normal;
        width: 100%;
        padding: 0;
    }
}
.hero-subtitle { font-size: 0.9rem; color: rgba(255, 255, 255, 0.5); text-transform: uppercase; letter-spacing: 4px; margin-bottom: 10px; display: block; }

.custom-accordion .accordion-item { 
    background: rgba(255, 255, 255, 0.03) !important; 
    border-radius: 15px !important; 
    margin-bottom: 12px;
    border: none !important;
    overflow: hidden;
    transition: 0.3s;
}
.custom-accordion .accordion-button { 
    background: transparent !important; 
    color: white !important; 
    font-weight: bold; 
    border-radius: 0 !important; 
    padding: 18px 20px;
    box-shadow: none !important;
}
.custom-accordion .accordion-button:not(.collapsed) { 
    color: #fe2c55 !important; 
    background: rgba(254, 44, 85, 0.05) !important;
    border-left: 4px solid #fe2c55 !important;
}
.custom-accordion .accordion-body {
    border-left: 4px solid #fe2c55;
    padding: 0 20px 20px 20px !important;
    color: rgba(255, 255, 255, 0.7);
}

.testimonial-card { 
    background: rgba(255, 255, 255, 0.03); 
    border: 1px solid rgba(255, 255, 255, 0.08); 
    padding: 25px; 
    border-radius: 20px; 
    transition: 0.3s; 
    height: 100%; 
    display: flex;
    flex-direction: column;
}
.bg-tiktok { background: #fe2c55 !important; }
.stars { color: #ffc107; font-size: 0.75rem; }
.avatar-sm { width: 35px; height: 35px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }

footer { background: rgba(10, 25, 47, 0.95); border-top: 1px solid rgba(255, 215, 0, 0.1); padding: 60px 20px; margin-top: 50px; }
.contact-item { width: 45px; height: 45px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 215, 0, 0.2); border-radius: 12px; display: flex; align-items: center; justify-content: center; color: white; text-decoration: none; transition: 0.3s; }
.contact-item:hover { background: #ffd700; color: #0a192f; transform: translateY(-3px); }

.whatsapp-premium { position: fixed; bottom: 30px; right: 30px; background: linear-gradient(135deg, #25d366 0%, #128c7e 100%); color: #fff !important; border-radius: 50px; padding: 12px 28px; z-index: 1000; display: flex; align-items: center; gap: 12px; text-decoration: none !important; box-shadow: 0 10px 30px rgba(18, 140, 126, 0.3); }

nav#nav-menu { position: fixed; top: 0; right: -100%; width: 280px; height: 100vh; background: #0a192f; transition: 0.3s ease; z-index: 2000; box-shadow: -5px 0 15px rgba(0,0,0,0.5); }
nav#nav-menu.active { right: 0; }
nav ul { list-style: none; padding: 80px 20px; }
nav ul li a { display: block; padding: 15px; color: white !important; text-decoration: none; font-weight: bold; border-bottom: 1px solid rgba(255,255,255,0.05); }

.section, .widget, .main-inner { margin: 0 !important; padding: 0 !important; }

/* Desktop Orders Sidebar */
@media (min-width: 992px) {
    .orders-sidebar {
        position: sticky;
        top: 90px;
        width: 100%;
        height: fit-content;
        max-height: calc(100vh - 120px);
        background: rgba(30, 41, 59, 0.7);
        backdrop-filter: blur(15px);
        border: 5px solid rgba(254, 44, 85, 0.3); /* 5px border as requested */
        border-radius: 20px;
        padding: 15px;
        overflow-y: auto;
        z-index: 900;
    }
    .sidebar-title {
        font-size: 1rem;
        font-weight: 800;
        color: #ffd700;
        margin-bottom: 15px;
        display: flex;
        align-items: center;
        gap: 10px;
        border-bottom: 1px solid rgba(255, 215, 0, 0.2);
        padding-bottom: 8px;
    }
    .sidebar-order-card {
        background: rgba(255, 255, 255, 0.03);
        border: 1px solid rgba(255, 255, 255, 0.05);
        border-radius: 12px;
        padding: 10px;
        margin-bottom: 10px;
        transition: 0.3s;
    }
    .sidebar-order-card:hover {
        border-color: #fe2c55;
        background: rgba(254, 44, 85, 0.05);
    }
    .sidebar-order-card .badge {
        font-size: 0.55rem;
        padding: 3px 6px;
    }
    .sidebar-order-card .time {
        font-size: 0.65rem;
        color: rgba(255, 255, 255, 0.4);
    }
    /* Custom scrollbar for sidebar */
    .orders-sidebar::-webkit-scrollbar { width: 4px; }
    .orders-sidebar::-webkit-scrollbar-track { background: transparent; }
    .orders-sidebar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.1); border-radius: 10px; }
}

style.b:if:
#blog-wrapper { display: none; }

#dashboard-wrapper { display: none; }
#blog-wrapper { display: block !important; }

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
    const siteConfig = {
        payments: {
            'bKash': { number: '01845464034', type: 'Personal' },
            'Nagad': { number: '01845464034', type: 'Personal' }
        },
        rates: {
            'Video Views': { view: 21, like: 10, comment: 0, follower: 0 },
            'Likes & Comments': { view: 20, like: 0, comment: 10, follower: 0 },
            'More Followers': { view: 17, like: 0, comment: 0, follower: 3.1 }
        },
        coinRate: 2,
        whatsappNumber: '8801845464034',
        socialLinks: {
            facebook: 'https://facebook.com/coinstorebd',
            whatsapp: 'https://wa.me/8801845464034',
            youtube: 'https://youtube.com/@coinstorebd',
            telegram: 'https://t.me/coinstorebd',
            tiktok: 'https://tiktok.com/@coinstorebd',
            location: 'https://maps.google.com/?q=Your+Location'
        }
    };

    window.copyNumber = function() {
        const num = document.getElementById('payment_number').innerText;
        navigator.clipboard.writeText(num).then(() => {
            alert("নম্বরটি কপি করা হয়েছে: " + num);
        }).catch(err => {
            console.error('Copy failed: ', err);
        });
    };

    window.switchTab = function(type) {
        const form = document.querySelector('form');
        if(form) form.reset(); // Reset all fields

        // Hide payment info box after reset
        const payBox = document.getElementById('payment_info_box');
        if(payBox) payBox.classList.add('d-none');

        const coinSec = document.getElementById('coin-section'),
              boostSec = document.getElementById('boost-section'),
              coinTab = document.getElementById('coin-tab'),
              boostTab = document.getElementById('boost-tab'),
              input = document.getElementById('service_type_input'),
              btn = document.getElementById('submit-btn');

        if(type === 'coin') {
            coinSec.style.display = 'block'; boostSec.style.display = 'none';
            coinTab.classList.add('active'); boostTab.classList.remove('active');
            input.value = 'Coin';
            calculateCoinPrice(); // Recalculate for default value
            if(btn) btn.innerHTML = `কয়েন অর্ডার করুন <i class="bi bi-arrow-right-circle ms-2"/>`;
        } else {
            coinSec.style.display = 'none'; boostSec.style.display = 'block';
            coinTab.classList.remove('active'); boostTab.classList.add('active');
            input.value = 'Boost';
            calculateEstimates(); // Recalculate for default value
            if(btn) btn.innerHTML = `বুস্ট অর্ডার করুন <i class="bi bi-arrow-right-circle ms-2"/>`;
        }
    };

    window.updateCoins = function(change) {
        const input = document.getElementById('coin_val');
        let newVal = (parseInt(input.value) || 50) + change;
        if (newVal < 50) newVal = 50;
        input.value = newVal;
        calculateCoinPrice();
    };

    window.updateBudget = function(change) {
        const input = document.getElementById('budget_val');
        let newVal = (parseInt(input.value) || 200) + change;
        if (newVal < 200) newVal = 200;
        input.value = newVal;
        calculateEstimates();
    };

    window.calculateCoinPrice = function() {
        const input = document.getElementById('coin_val'),
              infoDiv = document.getElementById('coin_price_info'),
              amount = parseInt(input.value) || 0,
              total = amount * siteConfig.coinRate;

        if (amount >= 50) {
            infoDiv.innerHTML = `<i class="bi bi-info-circle me-1"></i> মোট দাম: <span id='total_price_val' style="color:#25f4ee; font-weight:bold;">${total.toLocaleString()} টাকা</span> (১টি = ${siteConfig.coinRate} টাকা)`;
        } else {
            infoDiv.innerHTML = `<i class="bi bi-info-circle me-1"></i> ১টি কয়েন = ${siteConfig.coinRate} টাকা (সর্বনিম্ন ৫০টি)`;
        }
    };

    function animateNumber(id, finalValue) {
        const el = document.getElementById(id);
        if (!el) return;
        let startTime = null;
        const duration = 800;
        function step(timestamp) {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            const easeProgress = progress * (2 - progress);
            el.innerText = Math.floor(easeProgress * finalValue).toLocaleString();
            if (progress < 1) window.requestAnimationFrame(step);
        }
        window.requestAnimationFrame(step);
    }

    window.calculateEstimates = function() {
        const type = document.getElementById('promo_type').value,
              budget = parseInt(document.getElementById('budget_val').value) || 0,
              results = document.getElementById('estimate_results'),
              rates = siteConfig.rates[type] || {};

        let html = `<hr style="border-top: 1px dashed rgba(255, 255, 255, 0.2); margin: 10px 0;"><div class="d-flex flex-wrap justify-content-center gap-3"><div class="estimate-badge"><span class="lowest-badge">সর্বনিম্ন <i class="bi bi-caret-right-fill ms-1" style="color: #24E8E3;"></i></span></div>`,
            animTasks = [];

        if(rates.view) {
            const val = Math.floor(budget * rates.view);
            html += `<div class="estimate-badge"><i class="bi bi-eye"></i><label>ভিউ:</label><span class="count-target" id="anim-view">0</span></div>`;
            animTasks.push({ id: 'anim-view', val: val });
        }

        if(type === 'Video Views' && rates.like) {
            const val = Math.floor(budget * rates.like);
            html += `<div class="estimate-badge"><i class="bi bi-heart"></i><label>লাইক:</label><span class="count-target" id="anim-secondary">0</span></div>`;
            animTasks.push({ id: 'anim-secondary', val: val });
        } else if(type === 'Likes & Comments') {
            const val = Math.floor(budget * (rates.like || rates.comment));
            html += `<div class="estimate-badge"><i class="bi bi-heart"></i><label>লাইক, কমেন্ট:</label><span class="count-target" id="anim-secondary">0</span></div>`;
            animTasks.push({ id: 'anim-secondary', val: val });
        } else if(type === 'More Followers' && rates.follower) {
            const val = Math.floor(budget * rates.follower);
            html += `<div class="estimate-badge"><i class="bi bi-person-plus"></i><label>ফলোয়ার:</label><span class="count-target" id="anim-secondary">0</span></div>`;
            animTasks.push({ id: 'anim-secondary', val: val });
        }

        results.innerHTML = html + `</div>`;
        animTasks.forEach(task => animateNumber(task.id, task.val));
    };

    window.updatePaymentInfo = function() {
        const method = document.getElementById('payment_method').value,
              box = document.getElementById('payment_info_box'),
              num = document.getElementById('payment_number'),
              methodDisp = document.getElementById('method_display'),
              accType = document.getElementById('account_type');

        if(method && siteConfig.payments[method]) {
            num.innerText = siteConfig.payments[method].number;
            methodDisp.innerText = method;
            accType.innerText = siteConfig.payments[method].type;
            box.classList.remove('d-none');
        } else {
            box.classList.add('d-none');
        }
    };

    window.validateTikTokForm = function() {
        const type = document.getElementById('service_type_input').value,
              trxid = document.getElementsByName('trxid')[0].value.trim(),
              whatsapp = document.getElementsByName('whatsapp')[0].value,
              method = document.getElementById('payment_method').value,
              payNum = document.getElementById('payment_number').innerText;

        if (!method) { alert("অনুগ্রহ করে একটি পেমেন্ট মাধ্যম নির্বাচন করুন।"); return false; }
        if (!trxid) { alert("অনুগ্রহ করে ট্রানজেকশন আইডি দিন।"); return false; }

        let orders = JSON.parse(localStorage.getItem('coinstore_orders') || '[]');

        // Duplicate Check
        if (orders.some(o => o.trxid === trxid)) {
            document.getElementById('errorMessage').innerText = "অর্ডার অলরেডি করা হয়েছে!";
            document.getElementById('errorModal').style.display = 'flex';
            return false;
        }

        const order = { type, trxid, whatsapp, method, paymentNumber: payNum, date: new Date().toLocaleString() };

        if(type === 'Coin') {
            order.amount = document.getElementById('coin_val').value;
            order.total = document.getElementById('total_price_val').innerText;
        } else {
            order.promo = document.getElementById('promo_type').options[document.getElementById('promo_type').selectedIndex].text;
            order.budget = document.getElementById('budget_val').value;
            order.videoLink = document.getElementById('video_link').value;
            if(!order.videoLink) { alert("অনুগ্রহ করে একটি টিকটক ভিডিও লিংক দিন।"); return false; }
        }

        orders.unshift(order);
        localStorage.setItem('coinstore_orders', JSON.stringify(orders));
        loadRecentOrders();

        document.getElementById('successTitle').innerText = "অর্ডার সফল হয়েছে!";
        document.getElementById('successMessage').innerText = `আপনার ট্রানজেকশন আইডি (${trxid}) আমরা পেয়েছি। শীঘ্রই আপনার সার্ভিসটি প্রসেস করা হবে।`;
        document.getElementById('successModal').style.display = 'flex';
        return false;
    };

    window.loadRecentOrders = function() {
        const sidebar = document.getElementById('sidebar-orders-list');
        if(!sidebar) return;
        const orders = JSON.parse(localStorage.getItem('coinstore_orders') || '[]');
        if(orders.length === 0) {
            sidebar.innerHTML = `<div class='text-center py-5 text-white-50 small'><i class='bi bi-inbox d-block fs-2 mb-2'></i>কোনো অর্ডার পাওয়া যায়নি</div>`;
            return;
        }
        let html = '';
        orders.slice(0, 3).forEach(order => {
            const orderDateObj = new Date(order.date),
                  timeStr = orderDateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  diffMinutes = (new Date().getTime() - orderDateObj.getTime()) / (1000 * 60);
            let statusBadge = 'Completed', statusColor = '#2ecc71';
            if (diffMinutes < 1) { statusBadge = 'Received'; statusColor = '#25d366'; }
            else if (diffMinutes <= 20) { statusBadge = 'Pending'; statusColor = '#ffc107'; }

            html += `<div class='sidebar-order-card' onclick="document.getElementById('header_trxid_search').value='${order.trxid}'; checkStatus();" style="cursor:pointer; position:relative; overflow:hidden;"><div style='position:absolute; left:0; top:0; bottom:0; width:4px; background:${statusColor}; opacity:0.6;'></div><div class='d-flex justify-content-between align-items-start mb-2'><div class='d-flex align-items-center gap-2'><div class='rounded-circle d-flex align-items-center justify-content-center' style='width:24px; height:24px; background:rgba(254,44,85,0.1); color:#fe2c55;'><i class='bi ${order.type === "Coin" ? "bi-coin" : "bi-rocket-takeoff"}' style='font-size:0.75rem;'></i></div><span class='fw-bold text-white' style='font-size:0.8rem;'>${order.type}</span></div><span class='time' style='font-size:0.65rem; opacity:0.5;'>${timeStr}</span></div><div class='small text-white-50 truncate mb-2 font-monospace' style='font-size:0.7rem; letter-spacing:0.5px;'>TrxID: <span class='text-white'>${order.trxid}</span></div><div class='d-flex justify-content-between align-items-center'><span class='small' style='font-size:0.65rem; color:${statusColor}; font-weight:700; text-transform:uppercase;'>${statusBadge}</span><i class='bi bi-chevron-right text-white-50' style='font-size:0.7rem;'></i></div></div>`;
        });
        if(orders.length > 3) html += `<div class='text-center mt-2'><small class='text-white-50' style='font-size:0.7rem;'>+${orders.length - 3} more orders</small></div>`;
        sidebar.innerHTML = html;
    };

    window.checkStatus = function() {
        const trxid = document.getElementById('header_trxid_search').value.trim();
        if(!trxid) { alert("দয়া করে TrxID দিন"); return; }
        const orders = JSON.parse(localStorage.getItem('coinstore_orders') || '[]');
        const order = orders.find(o => o.trxid === trxid);
        const resultDiv = document.getElementById('statusResult');
        if(order) {
            // Mobile-friendly date parsing
            let orderTimeStr = "N/A";
            let diffMinutes = 999;

            // order.date format is "M/D/YYYY, h:mm:ss AM/PM"
            const parts = order.date.split(/[\/, :]+/);
            if (parts.length >= 6) {
                const month = parseInt(parts[0]) - 1;
                const day = parseInt(parts[1]);
                const year = parseInt(parts[2]);
                let hour = parseInt(parts[3]);
                const minute = parseInt(parts[4]);
                const second = parseInt(parts[5]);
                const ampm = parts[6];

                if (ampm === 'PM' && hour < 12) hour += 12;
                if (ampm === 'AM' && hour === 12) hour = 0;

                const orderDateObj = new Date(year, month, day, hour, minute, second);
                orderTimeStr = orderDateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });
                diffMinutes = (new Date().getTime() - orderDateObj.getTime()) / (1000 * 60);
            }

            let statusText = "Completed", statusColor = "#2ecc71";
            if (diffMinutes < 1) { statusText = "Received"; statusColor = "#25d366"; }
            else if (diffMinutes >= 1 && diffMinutes <= 20) { statusText = "Pending"; statusColor = "#ffc107"; }

            document.getElementById('statusModalTitle').innerHTML = `অর্ডার স্ট্যাটাস`;

            // Construct detailed WhatsApp message in Bangla
            let waDetails = `ধরন: ${order.type}%0A- TrxID: ${order.trxid}%0A- ফোন: ${order.whatsapp}`;
            if(order.type === 'Coin') {
                waDetails += `%0A- কয়েনের পরিমাণ: ${order.amount}%0A- মোট দাম: ${order.total}`;
            } else {
                waDetails += `%0A- প্রমোটের ধরন: ${order.promo || 'N/A'}%0A- বাজেট: ${order.budget || 'N/A'} টাকা%0A- ভিডিও লিংক: ${order.videoLink || 'N/A'}`;
            }
            const waMessage = `আসসালামু আলাইকুম! আমার অর্ডার তথ্য:%0A${waDetails}%0Aদয়া করে আমার অর্ডারটি দ্রুত প্রসেস করুন।`;

            resultDiv.innerHTML = `<div class='text-center mb-4 pb-3 border-bottom border-secondary border-opacity-10'><div class='d-inline-flex align-items-center gap-2 px-3 py-1 rounded-pill mb-2' style='background:${statusColor}15; border:1px solid ${statusColor}33;'><span class='rounded-circle' style='width:8px; height:8px; background:${statusColor}; box-shadow:0 0 10px ${statusColor};'></span><span style='color:${statusColor}; font-weight:700; font-size:0.85rem; text-transform:uppercase; letter-spacing:0.5px;'>${statusText}</span></div><div class='d-flex align-items-center justify-content-center gap-2 text-white-50 mt-1'><i class='bi bi-clock-history small'></i><span class='small fw-medium' style='letter-spacing:0.5px;'>অর্ডার টাইম: <span class='text-white'>${orderTimeStr}</span></span></div></div><div class='p-3 rounded-4' style='background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.08);'><div class='d-flex justify-content-between mb-2 pb-2 border-bottom border-secondary border-opacity-25'><span class='small text-white-50'>সার্ভিস টাইপ</span><span class='small fw-bold text-white'>${order.type} Order</span></div><div class='d-flex justify-content-between mb-2 pb-2 border-bottom border-secondary border-opacity-25'><span class='small text-white-50'>ট্রানজেকশন আইডি</span><span class='small fw-bold text-white font-monospace'>${order.trxid}</span></div><div class='d-flex justify-content-between mb-2 pb-2 border-bottom border-secondary border-opacity-25'><span class='small text-white-50'>পেমেন্ট মেথড</span><span class='small fw-bold text-white'>${order.method}</span></div>${order.type === 'Coin' ? `<div class='d-flex justify-content-between mb-2 pb-2 border-bottom border-secondary border-opacity-25'><span class='small text-white-50'>কয়েন পরিমাণ</span><span class='small fw-bold text-white'>${order.amount}</span></div><div class='d-flex justify-content-between'><span class='small text-white-50'>মোট দাম</span><span class='small fw-bold text-info'>${order.total}</span></div>` : `<div class='d-flex justify-content-between mb-2 pb-2 border-bottom border-secondary border-opacity-25'><span class='small text-white-50'>প্রমোটের ধরন</span><span class='small fw-bold text-white'>${order.promo}</span></div><div class='d-flex justify-content-between mb-2 pb-2 border-bottom border-secondary border-opacity-25'><span class='small text-white-50'>বাজেট</span><span class='small fw-bold text-info'>${order.budget} টাকা</span></div><div class='d-flex justify-content-between'><span class='small text-white-50'>ভিডিও লিংক</span><a href='${order.videoLink}' target='_blank' class='small fw-bold' style='color:#fe2c55; text-decoration:none;'>লিংক দেখুন <i class='bi bi-box-arrow-up-right ms-1'></i></a></div>`}</div><div class='mt-4 text-center'><p class='small text-white-50 mb-2'>দ্রুত সার্ভিস পেতে সাপোর্ট এ চ্যাট করুন</p><hr style='border-top: 1px dotted rgba(255, 255, 255, 0.2); margin: 15px 0;'/><a href='https://wa.me/${siteConfig.whatsappNumber}?text=${waMessage}' target='_blank' class='btn btn-success w-100 py-3 border-0 shadow-lg d-flex align-items-center justify-content-center gap-2' style='background:linear-gradient(135deg, #25d366 0%, #128c7e 100%); border-radius:15px; font-weight:800; letter-spacing:0.5px;'><i class='fab fa-whatsapp fs-4'></i> Chat Now</a></div>`;
        } else {
            resultDiv.innerHTML = `<div class='text-center p-4 text-white-50'><i class='bi bi-search fs-1 d-block mb-2'/><br/>দুঃখিত! এই TrxID দিয়ে কোনো অর্ডার পাওয়া যায়নি।</div>`;
        }
        document.getElementById('statusModal').style.display = 'flex';
    };

    function populatePaymentMethods() {
        const select = document.getElementById('payment_method');
        if (!select) return;
        for (const method in siteConfig.payments) {
            const option = document.createElement('option');
            option.value = method;
            option.text = `${method} (${siteConfig.payments[method].type})`;
            select.add(option);
        }
    }

    // Initialize
    const waLink = siteConfig.socialLinks.whatsapp;
    document.getElementById('wa-float-btn').href = waLink;
    if(document.getElementById('wa-footer-link')) document.getElementById('wa-footer-link').href = waLink;
    if(document.getElementById('fb-footer-link')) document.getElementById('fb-footer-link').href = siteConfig.socialLinks.facebook;
    if(document.getElementById('yt-footer-link')) document.getElementById('yt-footer-link').href = siteConfig.socialLinks.youtube;
    if(document.getElementById('tiktok-footer-link')) document.getElementById('tiktok-footer-link').href = siteConfig.socialLinks.tiktok;

    populatePaymentMethods();
    calculateCoinPrice();
    loadRecentOrders();
});
